Here is the full JSON schema tool spec for `mcp__firecrawl__firecrawl_search`:

---

mcp__firecrawl__firecrawl_search

Description:
Search web, news, or image sources and return ranked results. Operators include quoted phrases, `-term`, `site:host`, `inurl:term`, `intitle:term`, and `related:host`; the set is non-exhaustive. `includeDomains` and `excludeDomains` are mutually exclusive hostname filters; categories limit results to GitHub, research, PDF, or developer sources. For a programming question, add `categories: ["developer"]`. `categories: ["research"]` restricts web results to research-affiliated websites and returns page snippets. Each web result is a title, URL, and description; add `scrapeOptions` to attach page content in the same call (those fetches ignore `maxAge`). Returns source-type result groups and usage metadata.

Full JSON Schema (draft-07):

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "query": { "type": "string", "minLength": 1 },
    "highlights": { "type": "boolean" },
    "limit": { "type": "number" },
    "tbs": { "type": "string" },
    "filter": { "type": "string" },
    "location": { "type": "string" },

    "includeDomains": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 253,
        "pattern": "^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z0-9][a-z0-9-]{0,61}[a-z0-9]$"
      }
    },

    "excludeDomains": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 253,
        "pattern": "^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z0-9][a-z0-9-]{0,61}[a-z0-9]$"
      }
    },

    "sources": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "type": { "type": "string", "enum": ["web", "images", "news"] }
        },
        "required": ["type"],
        "additionalProperties": false
      }
    },

    "categories": {
      "type": "array",
      "items": { "type": "string", "enum": ["github", "research", "pdf", "developer"] }
    },

    "enterprise": {
      "type": "array",
      "items": { "type": "string", "enum": ["default", "anon", "zdr"] }
    },

    "scrapeOptions": {
      "type": "object",
      "properties": {
        "formats": {
          "type": "array",
          "items": { "type": "string", "enum": ["markdown", "html", "rawHtml", "screenshot", "links", "summary", "changeTracking", "branding", "json", "query", "audio"] }
        },
        "jsonOptions": {
          "type": "object",
          "properties": {
            "prompt": { "type": "string" },
            "schema": {
              "type": "object",
              "propertyNames": { "type": "string" },
              "additionalProperties": false,
              "properties": {}
            }
          },
          "additionalProperties": false
        },
        "queryOptions": {
          "type": "object",
          "properties": {
            "prompt": { "type": "string", "maxLength": 10000 },
            "mode": { "default": "freeform", "type": "string", "enum": ["directQuote", "freeform"] }
          },
          "required": ["prompt", "mode"],
          "additionalProperties": false
        },
        "screenshotOptions": {
          "type": "object",
          "properties": {
            "fullPage": { "type": "boolean" },
            "quality": { "type": "number" },
            "viewport": {
              "type": "object",
              "properties": { "width": { "type": "number" }, "height": { "type": "number" } },
              "required": ["width", "height"],
              "additionalProperties": false
            }
          },
          "additionalProperties": false
        },
        "parsers": { "type": "array", "items": { "type": "string", "enum": ["pdf"] } },
        "pdfOptions": {
          "type": "object",
          "properties": { "maxPages": { "type": "integer", "minimum": 1, "maximum": 10000 } },
          "additionalProperties": false
        },
        "onlyMainContent": { "type": "boolean" },
        "redactPII": { "type": "boolean" },
        "includeTags": { "type": "array", "items": { "type": "string" } },
        "excludeTags": { "type": "array", "items": { "type": "string" } },
        "waitFor": { "type": "number" },
        "mobile": { "type": "boolean" },
        "skipTlsVerification": { "type": "boolean" },
        "removeBase64Images": { "type": "boolean" },
        "location": {
          "type": "object",
          "properties": {
            "country": { "type": "string" },
            "languages": { "type": "array", "items": { "type": "string" } }
          },
          "additionalProperties": false
        },
        "storeInCache": { "type": "boolean" },
        "zeroDataRetention": { "type": "boolean" },
        "maxAge": { "type": "number" },
        "lockdown": { "type": "boolean" },
        "proxy": { "type": "string", "enum": ["basic", "stealth", "enhanced", "auto"] },
        "profile": {
          "type": "object",
          "properties": { "name": { "type": "string" }, "saveChanges": { "type": "boolean" } },
          "required": ["name"],
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    }
  },
  "required": ["query"],
  "additionalProperties": false
}

---

Key notes:
- `query` is the only required field.
- `includeDomains` / `excludeDomains` are mutually exclusive hostname filters (pattern-validated).
- `sources` selects result type: web, images, or news.
- `categories` restricts to github / research / pdf / developer.
- `scrapeOptions` attaches scraped page content to the same response (its fetches ignore `maxAge`).
- Top-level object disallows additional properties.
